                marketplaceDetails: marketplaceDetails,
                userDetailsEmail: userDetailsEmail,
                delegatedSubnetId: delegatedSubnetId,
                performanceTier: default,
                clusterLoginUri: clusterLoginUri,
                privateIPs: privateIPs);
        }
